    <button class="btn sm primary"><?= e($sf->t('save')) ?></button><button class="btn sm danger" name="delete" value="1" formnovalidate><?= e($sf->t('delete')) ?></button></form><?php endforeach; ?>
  <form method="post" action="<?= $post('field') ?>" class="row"><?= csrf_field() ?><input type="hidden" name="section_id" value="<?= (int)$s['id'] ?>"><input name="label" maxlength="120" required placeholder="<?= e($sf->t('adm_new_field')) ?>"><select name="type"><?php foreach (Svc::FIELD_TYPES as $t): ?><option value="<?= e($t) ?>"><?= e($sf->t('ft_' . $t)) ?></option><?php endforeach; ?></select><textarea name="options" rows="1" placeholder="<?= e($sf->t('adm_options')) ?>"></textarea>
